function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // stick figures
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 50);
  ctx.lineTo(W/2 - 80, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();

  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 20);
  ctx.lineTo(W/2 + 50, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 50);
  ctx.lineTo(W/2 + 80, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // losing self in other
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 100);
  ctx.lineTo(W/2 + 50, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + Math.sin(t) * 20, H/2 + 100);
  ctx.lineTo(W/2 + 50 + Math.sin(t + Math.PI) * 20, H/2 + 100);
  ctx.stroke();

  // fading self
  ctx.globalAlpha = 0.5 + Math.sin(t) * 0.2;
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 50);
  ctx.lineTo(W/2 - 80, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.globalAlpha = 1;

  ctx.restore();
}
